import React from 'react';
import { View, Image, FlatList, StyleSheet, Text, TouchableOpacity, Dimensions } from 'react-native';
// import { Ionicons } from '@expo/vector-icons'; // Assuming Expo

const { width } = Dimensions.get('window');
const ITEM_WIDTH = width * 0.4;

interface VideoFeedProps {
  data: any[];
  onPress: (item: any) => void;
}

const VideoFeed: React.FC<VideoFeedProps> = ({ data, onPress }) => {
  const renderItem = ({ item }: { item: any }) => {
    // Fallback to image if video thumbnail not available
    const imageUrl = item.image || (item.images && item.images[0]?.url) || 'https://via.placeholder.com/300x500';
    
    return (
      <TouchableOpacity 
        style={styles.cardContainer} 
        onPress={() => onPress(item)}
        activeOpacity={0.8}
      >
        <Image source={{ uri: imageUrl }} style={styles.image} resizeMode="cover" />
        <View style={styles.overlay}>
           {/* Simulate Play Icon */}
          <View style={styles.playIconContainer}>
            <View style={styles.playIconTriangle} />
          </View>
          <Text style={styles.title} numberOfLines={2}>{item.name}</Text>
        </View>
      </TouchableOpacity>
    );
  };

  if (!data || data.length === 0) return null;

  return (
    <View style={styles.container}>
      <FlatList
        data={data}
        renderItem={renderItem}
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.listContent}
        keyExtractor={(item) => item.id.toString()}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    marginBottom: 20,
  },
  listContent: {
    paddingHorizontal: 10,
  },
  cardContainer: {
    width: ITEM_WIDTH,
    height: ITEM_WIDTH * 1.6, // 16:9 aspect ratioish vertical
    marginHorizontal: 5,
    borderRadius: 10,
    overflow: 'hidden',
    backgroundColor: '#000',
  },
  image: {
    width: '100%',
    height: '100%',
    opacity: 0.8,
  },
  overlay: {
    ...StyleSheet.absoluteFillObject,
    justifyContent: 'flex-end',
    padding: 8,
  },
  playIconContainer: {
    position: 'absolute',
    top: '40%',
    left: '40%',
    width: 30,
    height: 30,
    borderRadius: 15,
    backgroundColor: 'rgba(255,255,255,0.7)',
    justifyContent: 'center',
    alignItems: 'center',
    marginLeft: -5, // adjustment
    marginTop: -5,
  },
  playIconTriangle: {
    width: 0,
    height: 0,
    backgroundColor: 'transparent',
    borderStyle: 'solid',
    borderLeftWidth: 10,
    borderRightWidth: 0,
    borderBottomWidth: 6,
    borderTopWidth: 6,
    borderLeftColor: '#000',
    borderRightColor: 'transparent',
    borderBottomColor: 'transparent',
    borderTopColor: 'transparent',
    marginLeft: 2,
  },
  title: {
    color: '#fff',
    fontSize: 12,
    fontWeight: 'bold',
    textShadowColor: 'rgba(0,0,0,0.75)',
    textShadowOffset: { width: -1, height: 1 },
    textShadowRadius: 10,
  },
});

export default VideoFeed;
